entries[189775] = { ["name"] = "Mächtige Dämonenketten", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nSobald Akkelion besiegt ist, absorbiert Xhul'horac seine Macht und erhält 'Mächtige Dämonenketten'.\n\nVerbindet Spielercharaktere mit Teufelsketten, die pro Sekunde pro Stapel 1193 Feuerschaden verursachen. Spielercharaktere erhalten einen Stapel für jeden Spielercharakter, mit dem sie verbunden sind.\n\nBetroffene Spielercharakter können sich von den mit ihnen verbundenen Spielercharakteren entfernen, um die Ketten zu brechen. Das Brechen von 'Mächtige Dämonenketten' löst 'Dämonischer Rückschlag' aus." }
entries[189776] = { ["name"] = "Mächtige Dämonenketten", ["text"] = "Sofort\nVerbindet Spielercharaktere mit Teufelsketten, die pro Sekunde pro Stapel 1193 Feuerschaden verursachen. Spielercharaktere erhalten einen Stapel für jeden Spielercharakter, mit dem sie verbunden sind.\n\nBetroffene Spielercharakter können sich von den mit ihnen verbundenen Spielercharakteren entfernen, um die Ketten zu brechen." }
entries[189777] = { ["name"] = "Mächtige Dämonenketten", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerbindet Spielercharaktere mit Teufelsketten, die pro Sekunde pro Stapel 1193 Feuerschaden verursachen. Spielercharaktere erhalten einen Stapel für jeden Spielercharakter, mit dem sie verbunden sind.\n\nBetroffene Spielercharakter können sich von den mit ihnen verbundenen Spielercharakteren entfernen, um die Ketten zu brechen." }
entries[189778] = { ["name"] = "Mächtige Dämonenketten", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerbindet Spielercharaktere mit Teufelsketten, die pro Sekunde pro Stapel 1193 Feuerschaden verursachen. Spielercharaktere erhalten einen Stapel für jeden Spielercharakter, mit dem sie verbunden sind.\n\nBetroffene Spielercharakter können sich von den mit ihnen verbundenen Spielercharakteren entfernen, um die Ketten zu brechen." }
entries[189779] = { ["name"] = "Mächtiges schwarzes Loch", ["text"] = "Unbegrenzte Reichweite\nWirken in 3 sek.\nSobald Omnus besiegt ist, absorbiert Xhul'horac seine Macht und erhält 'Mächtiges schwarzes Loch'.\n\nReißt ein Loch in das Gewebe der Realität, fügt allen Spielercharakteren alle 1 Sek. 1136 körperlichen Schaden zu und zieht sie zum schwarzen Loch. Wenn ein Spielercharakter ins schwarze Loch gerät, löst er 'Singularität' aus." }
