entries[190394] = { ["name"] = "Dunkle Verbindung", ["text"] = "300 Meter Reichweite\nWirken in 1.5 sek.\nArchimonde erschafft eine dunkle Verbindung an der Position eines zufälligen Spielercharakters, die allen Spielercharakteren innerhalb von 8 Metern von der Zielposition 8522 Schattenschaden zufügt.\n\nWenn eine dunkle Verbindung innerhalb von 8 Metern von einer anderen erzeugt wird, fügt sie allen Spielercharakteren 11078 Schattenschaden zu." }
