entries[190399] = { ["name"] = "Mal der Legion", ["text"] = "Sofort\nArchimonde brandmarkt mehrere Spielercharaktere unterschiedlich lang mit dem Mal der Legion.\n\nWenn 'Mal der Legion' abläuft, verursacht der Effekt 51126 Schattenschaden und stößt alle Spielercharaktere innerhalb von 10 Metern zurück. Dieser Effekt wird gleichmäßig zwischen allen getroffenen Zielen aufgeteilt und erhöht ihren durch 'Mal der Legion' erlittenen Schaden 12 Sek. lang um 600%." }
